// Turn every email attachment / uploaded file into one item, with its content as base64.
// Unsupported types and small images (e-mail signature logos) are skipped.
const cfg = $('Config').first().json;
const ALLOWED = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const isEmail = Boolean(it.json.id && it.json.threadId);
  const fromRaw = it.json.from;
  const from = isEmail ? String(fromRaw?.text ?? fromRaw?.value?.[0]?.address ?? fromRaw ?? '') : 'web-form';
  const meta = {
    source: isEmail ? 'email' : 'web-form',
    message_id: isEmail ? String(it.json.id) : '',
    email_from: from.slice(0, 200),
    email_subject: isEmail ? String(it.json.subject ?? '').slice(0, 200) : '',
  };
  let usable = 0;
  for (const [key, bin] of Object.entries(it.binary || {})) {
    const name = String(bin.fileName || key).slice(0, 200);
    let mime = String(bin.mimeType || '').toLowerCase();
    if (mime === 'image/jpg') mime = 'image/jpeg';
    if (!ALLOWED.includes(mime) && /\.pdf$/i.test(name)) mime = 'application/pdf';
    if (!ALLOWED.includes(mime)) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    const kb = Math.round(buf.length / 1024);
    if (mime.startsWith('image/') && kb < cfg.min_image_kb) continue; // signature logo, not a receipt
    usable++;
    if (kb > cfg.max_file_mb * 1024) {
      out.push({ json: { ...meta, file_name: name, mime_type: mime, size_kb: kb, skip_reason: `File is larger than ${cfg.max_file_mb} MB` } });
      continue;
    }
    out.push({ json: { ...meta, file_name: name, mime_type: mime, size_kb: kb, b64: buf.toString('base64') } });
  }
  if (usable === 0) out.push({ json: { ...meta, file_name: '', mime_type: '', size_kb: 0, skip_reason: 'No PDF or image attachment to read' } });
}
return out;

